const json = (value) => JSON.stringify(value, null, 2);
const literal = (value) => JSON.stringify(value);

function tsType(schema = {}) {
  if (schema.enum) return schema.enum.map(literal).join(" | ");
  if (schema.oneOf || schema.anyOf)
    return (schema.oneOf ?? schema.anyOf).map(tsType).join(" | ");
  if (schema.allOf) return schema.allOf.map(tsType).join(" & ");
  if (schema.type === "array") return `Array<${tsType(schema.items)}>`;
  if (schema.type === "object" || schema.properties) {
    const required = new Set(schema.required ?? []);
    const fields = Object.entries(schema.properties ?? {}).map(
      ([key, child]) =>
        `  ${JSON.stringify(key)}${required.has(key) ? "" : "?"}: ${tsType(child)};`,
    );
    return fields.length
      ? `{\n${fields.join("\n")}\n}`
      : "Record<string, unknown>";
  }
  if (Array.isArray(schema.type))
    return schema.type.map((t) => tsType({ ...schema, type: t })).join(" | ");
  return (
    {
      string: "string",
      integer: "number",
      number: "number",
      boolean: "boolean",
      null: "null",
    }[schema.type] ?? "unknown"
  );
}

export function generateCode(
  api,
  { lang = "js", baseUrl, auth = "none", include = [], exclude = [] } = {},
) {
  const ts = lang === "ts";
  const selected = api.operations.filter((op) => {
    const match = [...op.tags, op.operationId, op.name].some(
      (v) => include.length === 0 || include.includes(v),
    );
    const denied = [...op.tags, op.operationId, op.name].some((v) =>
      exclude.includes(v),
    );
    return match && !denied;
  });
  const operations = selected.map((op) => ({
    ...op,
    inputType: tsType(op.inputSchema),
    outputType: tsType(op.responseSchema),
  }));
  const defaults = { baseUrl: baseUrl ?? api.server, authType: auth };
  const defs = operations
    .map(
      (op) => `  {
    name: ${literal(op.name)},
    description: ${literal(op.description || op.summary || `${op.method} ${op.path}`)},
    inputSchema: ${json(op.inputSchema)},
    execute: async (args${ts ? `: ${op.inputType}` : ""}, { signal }${ts ? ": { signal?: AbortSignal }" : ""} = {})${ts ? `: Promise<${op.outputType}>` : ""} => {
      validateInput(${ts ? "args as Record<string, unknown>" : "args"}, ${json(op.inputSchema)}, ${literal(op.name)});
      return request${ts ? `<${op.outputType}>` : ""}(${literal(op.method)}, ${literal(op.path)}, ${ts ? "args as Record<string, unknown>" : "args"}, signal);
    },
  }`,
    )
    .join(",\n");
  const tsHeader = ts
    ? `export type WebMCPAuth =
  | { type: 'none' }
  | { type: 'bearer'; token: string }
  | { type: 'apiKey'; in: 'header' | 'query'; name: string; value: string }
  | { type: 'basic'; username: string; password: string };
export interface WebMCPOptions { baseUrl?: string; headers?: Record<string, string>; auth?: WebMCPAuth; fetch?: typeof fetch; }
export interface WebMCPTool<A = unknown> { name: string; description: string; inputSchema: Record<string, unknown>; execute(args: A, options?: { signal?: AbortSignal }): Promise<unknown>; }
type InputSchema = { [key: string]: unknown; type?: string | string[]; required?: string[]; properties?: Record<string, InputSchema>; enum?: unknown[]; items?: InputSchema; };
`
    : "";
  return `// Generated by openapi-to-webmcp. Do not edit manually.
${tsHeader}
const DEFAULTS = ${json(defaults)};

function encode(value${ts ? ": unknown" : ""}) { return encodeURIComponent(String(value)); }

function validateInput(value${ts ? ": Record<string, unknown>" : ""}, schema${ts ? ": InputSchema" : ""}, label${ts ? ": string" : ""}) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(label + ' expects an object of arguments.');
  for (const key of schema.required ?? []) {
    if (!Object.prototype.hasOwnProperty.call(value, key) || value[key] === undefined) throw new Error('Missing required argument "' + key + '" for ' + label + '.');
    const rule = schema.properties?.[key];
    const item = value[key];
    if (rule?.type === 'object' && item && typeof item === 'object') {
      for (const nested of rule.required ?? []) if (!Object.prototype.hasOwnProperty.call(item, nested)) throw new Error('Missing required field "' + nested + '" in argument "' + key + '".');
    }
    if (rule?.type === 'array' && !Array.isArray(item)) throw new Error('Argument "' + key + '" must be an array.');
    if (rule?.type === 'string' && typeof item !== 'string') throw new Error('Argument "' + key + '" must be a string.');
    if ((rule?.type === 'number' || rule?.type === 'integer') && typeof item !== 'number') throw new Error('Argument "' + key + '" must be a number.');
    if (rule?.type === 'boolean' && typeof item !== 'boolean') throw new Error('Argument "' + key + '" must be a boolean.');
    if (rule?.enum && !rule.enum.includes(item)) throw new Error('Argument "' + key + '" must match one of its allowed values.');
  }
}

function applyAuth(url${ts ? ": URL" : ""}, headers${ts ? ": Headers" : ""}, auth${ts ? ": WebMCPAuth" : ""}) {
  if (!auth || auth.type === 'none') return url;
  if (auth.type === 'bearer') headers.set('Authorization', 'Bearer ' + auth.token);
  else if (auth.type === 'basic') headers.set('Authorization', 'Basic ' + btoa(auth.username + ':' + auth.password));
  else if (auth.type === 'apiKey') {
    if (auth.in === 'query') url.searchParams.set(auth.name, auth.value);
    else headers.set(auth.name, auth.value);
  }
  return url;
}

export function createWebMCPTools(options${ts ? ": WebMCPOptions" : ""} = {}) {
  const baseUrl = options.baseUrl ?? (DEFAULTS.baseUrl || globalThis.location?.origin);
  const commonHeaders = options.headers ?? {};
  if (DEFAULTS.authType !== 'none' && DEFAULTS.authType !== 'custom' && !options.auth) throw new Error('Configure credentials with options.auth; credentials are never embedded in generated code.');
  const auth${ts ? ": WebMCPAuth" : ""} = options.auth ?? { type: 'none' };
  const expectedAuth = DEFAULTS.authType === 'api-key' ? 'apiKey' : DEFAULTS.authType;
  if (expectedAuth !== 'none' && expectedAuth !== 'custom' && auth.type !== expectedAuth) throw new Error('options.auth.type must match the configured authentication strategy: ' + expectedAuth);
  const fetchImpl = options.fetch ?? globalThis.fetch;
  if (typeof fetchImpl !== 'function') throw new Error('Fetch API is unavailable; pass options.fetch.');

  async function request${ts ? "<T = unknown>" : ""}(method${ts ? ": string" : ""}, path${ts ? ": string" : ""}, args${ts ? ": Record<string, unknown>" : ""}, signal${ts ? "?: AbortSignal" : ""})${ts ? ": Promise<T>" : ""} {
    if (!baseUrl) throw new Error('No API base URL is configured. Set --base-url or options.baseUrl.');
    let url = new URL(baseUrl, globalThis.location?.origin);
    if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) throw new Error('The API base URL must use HTTP(S) and must not contain credentials.');
    const pathParams = new Set();
    const expandedPath = path.replace(/\\{([^}]+)\\}/g, (_, key) => {
      if (!Object.prototype.hasOwnProperty.call(args, key)) throw new Error('Missing path parameter: ' + key);
      pathParams.add(key); return encode(args[key]);
    });
    url = new URL(expandedPath.replace(/^\\//, ''), url.href.endsWith('/') ? url : url.href + '/');
    const headers = new Headers(commonHeaders);
    let body;
    const cookie = [];
    for (const [key, value] of Object.entries(args ?? {})) {
      if (value === undefined || pathParams.has(key)) continue;
      const parameter = PARAMETERS[method + ' ' + path]?.[key];
      if (key === 'body') { body = value; continue; }
      if (!parameter) continue;
      if (parameter.in === 'query') {
        for (const item of Array.isArray(value) ? value : [value]) url.searchParams.append(key, String(item));
      } else if (parameter.in === 'header') headers.set(key, String(value));
      else if (parameter.in === 'cookie') cookie.push(encode(key) + '=' + encode(value));
    }
    if (cookie.length) headers.set('Cookie', cookie.join('; '));
    if (body !== undefined) { headers.set('Content-Type', 'application/json'); body = JSON.stringify(body); }
    url = applyAuth(url, headers, auth);
    const response = await fetchImpl(url, { method, headers, ...(body === undefined ? {} : { body }), signal });
    const text = await response.text();
    let data;
    try { data = text ? JSON.parse(text) : null; } catch { data = text; }
    if (!response.ok) throw new Error('API request failed (' + response.status + ' ' + response.statusText + '): ' + (typeof data === 'string' ? data : JSON.stringify(data)));
    return ${ts ? "data as T" : "data"};
  }

  const PARAMETERS${ts ? ": Record<string, Record<string, { in: string }>>" : ""} = ${json(Object.fromEntries(operations.map((op) => [`${op.method} ${op.path}`, Object.fromEntries(op.parameters.map((p) => [p.name, { in: p.in }]))])))};
  const tools = [
${defs}
  ];
  return {
    tools,
    async register(modelContext${ts ? "?: { registerTool(tool: (typeof tools)[number]): Promise<unknown> }" : " = globalThis.document?.modelContext"}) {
      if (!modelContext || typeof modelContext.registerTool !== 'function') throw new Error('WebMCP is unavailable. Pass document.modelContext.');
      for (const tool of tools) await modelContext.registerTool(tool);
      return tools;
    },
  };
}
`;
}
